import Image from 'next/image';

function Hero() {
  return (
    <Image
      src="/hero.jpg"
      alt="Hero image"
      width={1200}
      height={600}
      priority // Load above the fold
      quality={85} // Balance quality and size
      placeholder="blur" // Show blur while loading
    />
  );
}

@font-face {
  font-family: 'Custom Font';
  src: url('custom-font.woff2') format('woff2'),
       url('custom-font.woff') format('woff');
  font-weight: 400;
  font-style: normal;
  font-display: swap; /* Show fallback immediately */
}

/* Reserve space for text to prevent layout shift */
.hero-title {
  font-family: 'Hero Font', system-ui, sans-serif;
  font-size: 2.5rem;
  line-height: 1.2;
  /* Reserve space equivalent to the rendered text */
  min-height: 3em;  
  /* Or use aspect-ratio for more precise control */
  aspect-ratio: 10/3;
}
